{
  "title": "EFF-bb47d82c Web logs overview",
  "panels": [
    {
      "grid": {"x": 0, "y": 0, "w": 48, "h": 4},
      "type": "markdown",
      "config": {
        "content": "## Web logs overview\n\nKey metrics for the Kibana sample web logs (`kibana_sample_data_logs`): request volume, visitor count, 5xx error volume and average response size, plus requests over time."
      }
    },
    {
      "grid": {"x": 0, "y": 4, "w": 12, "h": 5},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "count"}]
      }
    },
    {
      "grid": {"x": 12, "y": 4, "w": 12, "h": 5},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Unique visitors (client IPs)",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "unique_count", "field": "clientip"}]
      }
    },
    {
      "grid": {"x": 24, "y": 4, "w": 12, "h": 5},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "query": {"language": "kql", "expression": "response.keyword: 5*"},
        "metrics": [{"type": "primary", "operation": "count"}]
      }
    },
    {
      "grid": {"x": 36, "y": 4, "w": 12, "h": 5},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Average response size (bytes)",
        "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
        "metrics": [{"type": "primary", "operation": "average", "field": "bytes"}]
      }
    },
    {
      "grid": {"x": 0, "y": 9, "w": 48, "h": 12},
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "layers": [
          {
            "type": "line",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
            },
            "x": {"column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
            "y": [{"column": "count"}]
          }
        ],
        "axis": {"x": {"title": {"visible": false}}}
      }
    }
  ]
}
EOF
